const field=(key,label,value,unit='',extra={})=>({key,label,type:'number',value:String(value),unit,...extra});
const dateField=(key,label,value='2026-01-01')=>({key,label,type:'date',value});
const select=(key,label,value,options)=>({key,label,type:'select',value,options:options.map(([value,label])=>({value,label}))});
const text=(key,label,value='')=>({key,label,type:'text',value});
function n(v,key,{min=0,max=1e7,integer=false,positive=false}={}){if(v?.[key]==null||String(v[key]).trim()==='')throw new Error(`${key} is required.`);const x=Number(v[key]);if(!Number.isFinite(x)||x<min||x>max||(integer&&!Number.isInteger(x))||(positive&&x<=0))throw new Error(`${key} must be ${integer?'a whole number':'a number'} between ${min} and ${max}${positive?' (greater than zero)':''}.`);return x;}
function isoDate(v,key){const s=String(v?.[key]??'');if(!/^\d{4}-\d{2}-\d{2}$/.test(s))throw new Error(`${key} must be a valid calendar date.`);const d=new Date(`${s}T00:00:00Z`);if(Number.isNaN(d.getTime())||d.toISOString().slice(0,10)!==s)throw new Error(`${key} must be a valid calendar date.`);return d;}
function addDays(d,days){const x=new Date(d);x.setUTCDate(x.getUTCDate()+days);return x;}
const dayString=d=>d.toISOString().slice(0,10);
const r=(label,value,unit='',details=[],note)=>({label,value,unit,details,...(note?{note}:{})});
const bmi=(kg,cm)=>kg/((cm/100)**2);
const activity={sedentary:1.2,light:1.375,moderate:1.55,very:1.725,extra:1.9};
function msj(v){const kg=n(v,'weight',{min:20,max:350,positive:true}),cm=n(v,'height',{min:100,max:230,positive:true}),age=n(v,'age',{min:18,max:100,integer:true}),sex=v.sex==='male'?5:-161;return 10*kg+6.25*cm-5*age+sex;}
function fieldsEnergy(){return [field('weight','Weight',70,'kg',{min:20,max:350}),field('height','Height',170,'cm',{min:100,max:230}),field('age','Age',35,'years',{min:18,max:100,step:1}),select('sex','Equation sex term','female',[['female','Female coefficient'],['male','Male coefficient']])];}
const copy={
'bmi-calculator':['Calculate adult body mass index from height and weight, then see the standard adult screening category and the weight interval that corresponds to the healthy BMI range. The calculation is intended for adults and does not measure body fat directly.','BMI = weight in kilograms divided by height in metres squared. Categories are the CDC adult thresholds; for people under 20, interpretation requires age- and sex-specific growth charts.','At 70 kg and 1.75 m, BMI is 70/1.75² = 22.9.','Is BMI a diagnosis? No. It is a screening measure and should be considered with other health information.','Can I use this for a child? No. Children and teens need age- and sex-specific percentiles.'],
'calorie-calculator':['Estimate daily calorie maintenance from a resting-energy equation and an activity multiplier, then model a modest goal adjustment. This gives a planning starting point, not a measured metabolic rate or a prescribed diet.','The calculator applies Mifflin–St Jeor resting energy expenditure and multiplies by the selected activity factor. The goal adjustment is user-entered and is shown separately from estimated maintenance.','A 35-year-old, 70 kg, 170 cm woman estimates about 1,420 kcal/day at rest; a light-activity factor of 1.375 gives roughly 1,953 kcal/day maintenance.','Is the result my exact calorie need? No. It is an equation-based estimate and can differ from measured needs.','Does the goal adjustment guarantee weight change? No. Real intake, activity, health, and metabolic adaptation affect outcomes.'],
'body-fat-calculator':['Estimate adult body-fat percentage from BMI, age, and the sex term used in the published Deurenberg equation. Because this is inferred from height and weight rather than measured directly, treat it as a rough population equation, not a body-composition scan.','Deurenberg adult estimate: body fat % = 1.20×BMI + 0.23×age − 10.8×sex − 5.4, with male=1 and female=0 in the original equation.','A 30-year-old man with BMI 25 has an estimated body fat of about 27.6%.','Is this the same as a DEXA result? No. It is an indirect estimate with meaningful individual error.','Does the equation apply to children? No. The adult equation is not designed for children or adolescents.'],
'bmr-calculator':['Estimate basal metabolic rate, the energy used at rest, from age, height, weight, and the Mifflin–St Jeor equation. Use it as an estimate of resting needs before adding daily movement or exercise.','Mifflin–St Jeor: men 10W+6.25H−5A+5; women 10W+6.25H−5A−161, where W is kg, H is cm, and A is years. This estimates resting energy only; walking, work, exercise, and digestion add to total daily expenditure.','At 70 kg, 170 cm, and 35 years, the female-coefficient estimate is 1,402.5 kcal/day.','Is BMR the same as total daily energy expenditure? No. Total expenditure also includes activity and digestion.','Can an equation measure my metabolism? No. Indirect calorimetry is needed for a measurement.'],
'macro-calculator':['Turn a daily calorie target into grams of protein, carbohydrate, and fat using percentages that you choose. The tool checks that the three energy shares total 100%, making it useful for comparing macro plans on a consistent calorie basis.','Protein and carbohydrate provide about 4 kcal per gram; fat provides about 9 kcal per gram. Each macro’s grams equal allocated calories divided by its energy-per-gram factor.','For 2,000 kcal split 30% protein, 40% carbohydrate, and 30% fat, the estimates are 150 g, 200 g, and 66.7 g.','Does this tell me which macro split is medically right for me? No. Needs vary with health, training, preferences, and clinical advice.','Why must percentages add to 100? The three shares are defined as a complete allocation of the calorie target.'],
'ideal-weight-calculator':['Compare four classic height-based ideal-weight equations and show their average as a reference point. These formulas were devised for clinical estimates, so the spread is more informative than treating one result as a personal target.','The calculator evaluates Devine, Robinson, Miller, and Hamwi formulas using height above 5 feet, then averages their estimates. Each formula is a historical rule of thumb with a different derivation.','For a 5 ft 8 in adult, the four equations can differ by several kilograms; the average summarizes them without implying a required weight.','Is this a healthy weight prescription? No. These legacy equations do not account for body composition or an individual’s health context.','What if someone is shorter than 5 feet? The equations can produce poor estimates outside their usual adult height context.'],
'pregnancy-calculator':['Estimate an expected due date and gestational age from the first day of the last menstrual period, with an optional adjustment for a cycle length different from 28 days. Pregnancy dating is approximate and is commonly confirmed by ultrasound.','Estimated due date = LMP + 280 days + (usual cycle length − 28 days). Gestational age is counted from the first day of the last menstrual period.','An LMP of January 1 with a 28-day cycle gives an estimated due date of October 8.','Is this due date definitive? No. A clinician may revise dating based on ultrasound and clinical history.','Does the date predict the exact day of birth? No; it is an estimate used to track pregnancy timing.'],
'pregnancy-weight-gain-calculator':['Compare current pregnancy weight gain with widely used singleton or twin-pregnancy total ranges based on pre-pregnancy BMI. It also shows a simple progress comparison, while leaving individual targets to prenatal care.','The calculator selects the CDC-posted Institute of Medicine total-gain range using pre-pregnancy BMI and pregnancy type. A linear progress line is only a visual comparison, not a clinical trimester-specific growth model.','For a singleton pregnancy with pre-pregnancy BMI 22, the reference total gain is 25–35 lb (about 11.3–15.9 kg).','Are these ranges a personal medical goal? They are population recommendations; a prenatal clinician can individualize them.','Does the reference cover triplets? No. Ask a maternity-care professional for a multiple pregnancy beyond twins.'],
'pregnancy-conception-calculator':['Estimate a conception date from a due date or last menstrual period using conventional pregnancy dating intervals. The result is a calendar estimate because ovulation timing and cycle length vary from person to person.','A typical estimate places conception about 266 days before the estimated due date, or near 14 days after a 28-day-cycle LMP.','A due date of October 8 corresponds to an estimated conception date around January 15.','Can this identify the exact conception day? No. Ovulation and fertilization timing can vary.','Is this suitable for paternity or legal dating? No; use appropriate clinical testing and records.'],
'due-date-calculator':['Estimate a pregnancy due date using the last menstrual period, conception date, or IVF transfer date. The selected dating method matters, and a healthcare professional may confirm or revise the estimate with ultrasound.','LMP dating adds 280 days; conception dating adds 266 days; a day-5 embryo transfer adds 261 days. These are conventional estimates rather than a prediction of the delivery date.','A day-5 embryo transfer on March 1 gives an estimated due date 261 days later.','Which date should I trust? Use the date selected by your prenatal clinician, who can account for ultrasound and treatment details.','Does a due date mean labor begins that day? No. It is a reference point for pregnancy dating.'],
'pace-calculator':['Convert a running or walking distance and elapsed time into pace per kilometre or mile and average speed. The result helps compare workouts recorded in different distance units, provided the entered duration is moving time.','Pace = elapsed time ÷ distance. Speed = distance ÷ elapsed time. Unit conversion uses 1 mile = 1.609344 kilometres.','Running 5 km in 25 minutes is a pace of 5:00 min/km and an average speed of 12 km/h.','Does pace include stops? It does if your entered time includes stops. Use moving time for moving pace.','Can I enter seconds and hours together? Enter total hours, minutes, and seconds in the provided fields.'],
'army-body-fat-calculator':['Calculate waist-to-height ratio using the Army’s current body-composition screening measure and compare it with the published 0.55 standard. The tool does not estimate body-fat percentage; the Army replaced its former circumference tape test with this ratio in 2026.','Waist-to-height ratio = abdominal circumference at the navel ÷ height, using the same unit for both. Current Army guidance sets a screening standard below 0.55.','A 36-inch waist and 70-inch height produce a ratio of 0.514, below 0.55.','Does this return a body-fat percentage? No. It calculates the current Army screening ratio.','Is this an official Army assessment? No. Official measurements and eligibility decisions follow Army procedures.'],
'carbohydrate-calculator':['Translate a chosen share of daily calories into carbohydrate grams and compare it with the adult acceptable macronutrient distribution range. The range is a population reference, not an individualized treatment plan.','Carbohydrate provides about 4 kcal per gram, so grams = daily calories × carbohydrate percentage ÷ 100 ÷ 4. The adult reference range is 45–65% of calories.','At 2,000 kcal and 50% from carbohydrate, the estimate is 250 g per day.','Does this prescribe a low- or high-carbohydrate diet? No. It converts a selected percentage into grams.','Do people with diabetes need a tailored plan? Yes. Ask a qualified clinician or dietitian about individual needs.'],
'lean-body-mass-calculator':['Estimate lean body mass from total weight and a body-fat percentage estimate. The result represents everything outside the estimated fat mass, including water, bone, and muscle, rather than muscle alone.','Fat mass = body weight × body-fat fraction; lean body mass = body weight − fat mass. Because the input percentage is itself an estimate, any error in that percentage carries directly into the lean-mass result.','At 80 kg and an estimated 20% body fat, lean mass is 80×0.80 = 64 kg.','Is lean mass the same as skeletal muscle? No. Lean mass includes water, organs, bone, and other non-fat tissue.','How accurate is the output? It depends directly on the accuracy of the body-fat percentage you enter.'],
'healthy-weight-calculator':['Find the adult weight interval associated with BMI 18.5 through 24.9 at a given height. The interval is a screening reference; body build, age, pregnancy, and health conditions may make BMI-based ranges less useful.','For height h in metres, the weight interval is 18.5h² through 24.9h² kilograms. CDC adult BMI categories apply to adults 20 and older.','At 1.70 m, the corresponding weight interval is approximately 53.5–72.0 kg.','Does the range define the one right weight? No. It is a population screening range and not an individual medical target.','Can I use this for a teenager? No. Pediatric interpretation uses BMI-for-age percentiles.'],
'calories-burned-calculator':['Estimate calories used during a chosen activity from body weight, duration, and a MET intensity value. The MET value is an average from activity research, so the result is a comparison estimate rather than a wearable-grade measurement.','Approximate gross kcal = MET × 3.5 × weight(kg) ÷ 200 × minutes. MET values are standardized activity intensities; actual energy use varies with pace and physiology.','For a 70 kg person walking at 3.5 MET for 30 minutes, estimated gross expenditure is about 129 kcal.','Are these calories exact? No. A MET estimate cannot capture individual movement economy or actual intensity precisely.','Does gross calorie burn subtract resting energy? No. It includes the energy that would also be spent at rest during that time.'],
'one-rep-max-calculator':['Estimate the greatest load you could lift for one repetition from a submaximal set and repetitions completed. Compare Epley and Brzycki estimates, while treating the result as a training approximation rather than a safe substitute for a tested max.','Epley: 1RM = load×(1+reps/30). Brzycki: 1RM = load×36/(37−reps). Both are estimates and become less dependable at high repetition counts.','A 100 kg set of 5 reps estimates about 116.7 kg by Epley and 112.5 kg by Brzycki.','Should I attempt the estimated maximum? Not based on this number alone; use safe technique, suitable supervision, and your training context.','Why do formulas disagree? They fit different observed lifting data and approximate the strength-repetition relationship differently.'],
'target-heart-rate-calculator':['Estimate age-predicted maximum heart rate and moderate or vigorous training zones from the simple 220-minus-age rule. These broad ranges help frame exercise intensity but cannot account for medication, fitness, or heart conditions.','Estimated maximum = 220−age. Moderate zone is 50–70% and vigorous zone is 70–85% of that estimate, following American Heart Association guidance.','At age 40, estimated maximum is 180 bpm; the moderate zone is about 90–126 bpm.','Is 220 minus age exact? No. It is a population rule of thumb with substantial individual variation.','What if I take heart medication or have a heart condition? Ask a healthcare professional for an appropriate exercise range.'],
'protein-calculator':['Estimate daily protein grams by multiplying body weight by a selected grams-per-kilogram target. The target is configurable because protein needs depend on age, activity, health, and clinical goals.','Daily protein = weight in kg × selected grams of protein per kg per day. This calculator does not infer an optimal target from a medical diagnosis.','At 70 kg and a selected 1.2 g/kg target, the estimate is 84 g/day.','Is a higher target always better? No. Individual needs and kidney or other health conditions matter.','Does this calculate meal portions? No. It gives a daily gram estimate only.'],
'fat-intake-calculator':['Convert a chosen percentage of daily calories from fat into grams and show the corresponding calorie amount. This keeps the energy conversion transparent while allowing the user to select a target for comparison.','Fat provides about 9 kcal per gram, so fat grams = daily calories × selected percentage ÷ 100 ÷ 9. The percentage refers to energy share, not weight share; the calculation reports total fat and does not split fatty-acid types.','At 2,000 kcal with 30% from fat, the estimate is 600 kcal or about 66.7 g of fat.','Does the result distinguish saturated and unsaturated fat? No. It is total fat only.','Is 30% the right target for everyone? No; the appropriate pattern depends on personal health and dietary needs.'],
'tdee-calculator':['Estimate total daily energy expenditure by multiplying Mifflin–St Jeor resting energy expenditure by an activity factor. Separating the resting estimate from the activity multiplier makes assumptions visible when using the result for planning.','TDEE ≈ Mifflin–St Jeor REE × activity factor. Common planning factors range from 1.2 for sedentary to 1.9 for very high activity.','An estimated resting expenditure of 1,400 kcal/day with a 1.55 factor gives TDEE near 2,170 kcal/day.','Does this directly measure daily burn? No. Both the base equation and activity factor are estimates.','Can exercise be double-counted? Yes, if the activity factor already includes workouts and you then add workout calories again.'],
'ovulation-calculator':['Estimate a likely ovulation date and fertile window from the first day of the last period and usual cycle length. Calendar estimates cannot confirm ovulation, especially with irregular cycles.','A common estimate places ovulation about 14 days before the next period; the fertile window is approximated as five days before through one day after ovulation.','For a 28-day cycle starting on March 1, the estimate places ovulation near day 14 and the fertile window around March 9–15.','Can this confirm ovulation? No. It estimates from cycle timing only.','Does every cycle ovulate on day 14? No. Cycle length and ovulation timing vary.'],
'conception-calculator':['Estimate a likely conception window from the last menstrual period and typical cycle length, or work backward from an estimated due date. This is approximate calendar arithmetic and cannot establish the exact date of fertilization.','The estimate places ovulation about 14 days before the next expected period; conception is most likely around ovulation, with a wider possible window because sperm can remain viable for several days.','A 30-day cycle usually places the estimated ovulation around cycle day 16, rather than day 14.','Can this determine paternity? No. It is not precise enough for that purpose.','Why provide a window? Ovulation and fertilization are not known from a calendar estimate alone.'],
'period-calculator':['Project the next expected period, likely ovulation, and a broad fertile window from the last period and average cycle length. Use it as a cycle-planning aid, not as contraception or a diagnosis of cycle irregularity.','Next period = LMP + cycle length. Estimated ovulation is about 14 days before that date; the fertile window is approximated from five days before to one day after ovulation.','With a 29-day cycle beginning April 1, the next period is projected around April 30.','Can I rely on this to avoid pregnancy? No. Calendar tracking alone is not reliable contraception.','When should a clinician assess irregular periods? Seek individualized advice for persistent changes, unusually heavy bleeding, pain, or concern.'],
'gfr-calculator':['Estimate adult kidney filtration using the 2021 race-free CKD-EPI creatinine equation and a standardized serum creatinine result. eGFR is a screening estimate that clinicians interpret with urine albumin, trends, and other findings.','2021 CKD-EPI creatinine equation: 142×min(Scr/κ,1)^α×max(Scr/κ,1)^−1.200×0.9938^age×1.012 if female; κ and α depend on sex term.','For a 50-year-old man with standardized creatinine 1.0 mg/dL, the estimate is roughly 91 mL/min/1.73 m².','Does one low eGFR diagnose chronic kidney disease? No. Kidney abnormalities generally need persistence or other evidence, interpreted clinically.','Why does creatinine-based eGFR have limits? Muscle mass, diet, acute illness, and other factors can change creatinine independently of filtration.'],
'body-type-calculator':['Classify a clothing-fit silhouette from bust, waist, and hip measurements using transparent ratio rules. The output is a descriptive shape label for garment-fit exploration, not a health or personality category.','The comparison uses bust-to-hip and waist-to-bust/hip proportions with a small tolerance band to identify balanced, pear, inverted-triangle, or straighter silhouettes.','A larger hip measure than bust tends toward the pear-shaped fit category in this simple rule set.','Does body type say anything about health? No. These labels only compare external measurements.','Will this guarantee clothing fit? No. Brands and garment cuts use different sizing systems.'],
'body-surface-area-calculator':['Estimate body surface area from height and weight with the Mosteller equation. BSA is a derived measurement used in some clinical calculations, but medication dosing must follow the prescriber’s method and patient-specific guidance.','Mosteller BSA = √[height(cm)×weight(kg)/3600] square metres. This compact empirical equation estimates a surface-area index from two measurements; it does not model body shape and should not be substituted into a dose calculation without clinician direction.','At 170 cm and 70 kg, estimated BSA is about 1.82 m².','Can I use this to calculate a medicine dose? No. Follow the prescribing clinician’s validated dosing method.','Is Mosteller the only BSA formula? No; several methods exist and can give slightly different values.'],
'bac-calculator':['Produce a rough Widmark-style blood alcohol concentration estimate from alcohol amount, body weight, distribution factor, and elapsed time. The result is highly uncertain and must never be used to decide whether driving or operating equipment is safe.','Estimated BAC% ≈ alcohol grams ÷ (r×body weight grams) × 100 − 0.015×hours, floored at zero. Absorption, drink size, food, and metabolism vary widely.','A modelled estimate can change substantially if drink strength, body composition, or timing differs from the inputs.','Can this tell me if I am safe to drive? No. Do not use a calculator to make that decision.','Is the estimate a measured BAC? No. Only a suitable test can measure alcohol concentration.'],
'anorexic-bmi-calculator':['Calculate BMI and show how it compares with standard adult thresholds, including the very low BMI range below 16. The historical title is retained for search, but BMI cannot diagnose anorexia nervosa or determine someone’s nutritional status by itself.','BMI=weight(kg)/height(m)². Adult BMI under 16 is a very low screening value; eating-disorder diagnosis depends on clinical assessment, not a BMI threshold alone.','At 45 kg and 1.70 m, BMI is 15.6, a result that warrants careful medical context rather than self-diagnosis.','Does a low BMI prove anorexia nervosa? No. An eating disorder can occur at many body sizes and requires professional assessment.','What should I do if the number worries me? Contact a qualified healthcare professional; urgent symptoms need urgent care.'],
'weight-watchers-points-calculator':['Estimate a single food serving with a clearly labeled historical classic Points formula, or switch to a simple daily budget tracker. The food estimate uses calories, total fat, and dietary fiber from a label, making it useful for historical recipe comparisons rather than current plan tracking.','The historical formula in U.S. Patent 6,040,531 is calories/50 + total fat grams/12 − dietary fiber grams/5, with the result rounded to the nearest half point. This old formula is not the current proprietary WeightWatchers Points algorithm; modern programs use different nutrition factors and personalized rules.','A serving with 270 kcal, 14 g fat, and 4 g fiber gives 270/50 + 14/12 − 4/5 = 5.77, or about 6 historical points.','Does this match the current WeightWatchers app? No. It reconstructs a historical formula only and cannot reproduce current proprietary food scores.','Can I still track my own daily allowance? Yes. Select budget mode and enter a budget and the points you have logged.'],
'overweight-calculator':['Compare adult BMI with the standard BMI 25 screening threshold and estimate the weight corresponding to that threshold for a given height. The output is a screening comparison and does not judge body composition or an individual’s health.','BMI=weight(kg)/height(m)². The BMI-25 comparison weight is 25×height(m)²; the difference is shown only when current weight is above that reference. This is a screening threshold for adults, not a health boundary; muscularity, body composition, age, and clinical context all affect interpretation.','At 1.70 m, BMI 25 corresponds to 72.25 kg.','Does BMI above 25 mean I am unhealthy? No. BMI is one screening measure and should be interpreted with other information.','Is the same cutoff used for children? No. Children and teens use age- and sex-specific BMI percentiles.']
};

