macros:[field('calories','Daily calorie target',2000,'kcal',{min:500,max:10000}),field('protein','Protein share',30,'%',{min:0,max:100}),field('carbs','Carbohydrate share',40,'%',{min:0,max:100}),field('fat','Fat share',30,'%',{min:0,max:100})],
ideal:[field('height','Height',173,'cm',{min:130,max:230}),select('sex','Equation sex term','female',[['female','Female coefficients'],['male','Male coefficients']])],
