gain:[field('height','Pre-pregnancy height',165,'cm',{min:100,max:230}),field('preweight','Pre-pregnancy weight',65,'kg',{min:20,max:350}),field('gain','Weight gained so far',5,'kg',{min:-10,max:100}),field('week','Gestational week',20,'weeks',{min:1,max:42}),select('multiples','Pregnancy type','singleton',[['singleton','One baby'],['twins','Twins']])],
conception:[select('method','Known date','due',[['due','Estimated due date'],['lmp','Last menstrual period']]),dateField('date','Due date or LMP'),field('cycle','Usual cycle length',28,'days',{min:20,max:45,step:1})],
due:[select('method','Dating method','lmp',[['lmp','Last menstrual period'],['conception','Conception date'],['ivf','Day-5 embryo transfer']]),dateField('date','Selected date')],
pace:[field('distance','Distance',5,'km',{min:0.01,max:1000,positive:true}),select('unit','Distance unit','km',[['km','Kilometres'],['mi','Miles']]),field('hours','Hours',0,'h',{min:0,max:1000,step:1}),field('minutes','Minutes',25,'min',{min:0,max:59,step:1}),field('seconds','Seconds',0,'sec',{min:0,max:59,step:1})],
